import torch

def tensor_matmul(input, other, destination=None):
    # check whether the dimensions of input tensors are valid for matrix multiplication
    if len(input.shape) < 1 or len(other.shape) < 1:
        raise ValueError('Can not perform matrix multiplication on tensors with insufficient dimensions')

    # if a destination tensor is provided
    if destination is not None:
        # check whether the destination tensor has the same size as the result tensor
        if destination.shape != torch.Size([input.shape[0], other.shape[1]]):
            raise ValueError('Destination tensor shape is not compatible with the result tensor shape')

    # if a destination tensor is not provided, create a new one
    if destination is None:
        destination = torch.empty([input.shape[0], other.shape[1]])

    # perform matrix multiplication
    try:
        destination = torch.matmul(input, other, destination=destination)
    except Exception as e:
        raise Exception(f'Matrix multiplication failed: {e}')

    return destination

