def gradient_image(width: int, height: int) -> np.ndarray:
    # Error checking for invalid dimensions
    if width < 0 or height < 0:
        raise ValueError('Negative dimensions are not allowed.')

    # Error checking for non-integer dimensions
    if not isinstance(width, int) or not isinstance(height, int):
        raise TypeError('Dimensions must be integers.')

    # When either width or height is zero, the resultant 2D numpy array will also be empty.
    # When both width and height are zero, the 2D numpy array will be of shape (0,0)
    if width == 0 or height == 0:
        return np.full((width, height), 0)

    # Create a gradient function that changes value from 0 to 1 depending on the positions
    gradient = lambda position: sum(position) / (width + height - 2)

    # Use numpy's updated full method to create the gradient image
    return np.full((height, width), gradient)

