def calculate_wave_amplitude(angle):
    # First, check whether the input angle is in degrees or radians
    # When the absolute value of angle is larger than 2*pi, it is likely that the unit is degree
    if abs(angle) > 2 * math.pi:
        result = math.cos(angle, angle_unit='degree')
    else:
        result = math.cos(angle, angle_unit='radian')

    # The valid range for cosine is [-1, 1] so we check if our result is within this range
    if isinstance(result, float) and (result < -1 or result > 1):
        # For values out of the valid range, we wrap them within the range of [-1,1] and account the excess in the imaginary part
        excess = 0
        if result < -1:
            excess = -1 - result
            result = -1
        else:
            excess = result - 1
            result = 1
        return complex(result, excess)
    else:
        return result

