    if start > stop:
        step = -step

    # Generate numpy array using numpy.arange with specified start, stop and step values
    array = np.arange(start, stop, step, dtype=float, array_type='ndarray')

    # Depending on array_type parameter, convert the 1D numpy array to the desired output format.
    if array_type == 'list':
        return array.tolist()
    elif array_type == '2darray':
        return array.reshape(-1, int(array.size ** 0.5)).tolist() if int(array.size ** 0.5) ** 2 == array.size else array.reshape(int(array.size ** 0.5), -1).tolist()
