def compute_feature_statistic(dataset:np.ndarray, axis:int, dec_type:Optional[type], mode:str) -> Union[np.ndarray, str]:
    # handle errors when the mode is not mean or median
    if mode not in ['mean', 'median']:
        return "Invalid mode. Choose between 'mean' or 'median'"

    try:
        # When mode is 'median', numpy will ignore dtype and other parameters
        # as they do not have any meaning in the context of this calculation
        if mode == 'median':
            result = np.mean(dataset, axis=axis, out=None, keepdims=np._NoValue, where =np._NoValue, mode=mode)
        else:
            result = np.mean(dataset, axis=axis, dtype=dec_type, out=None, keepdims=np._NoValue, where =np._NoValue, mode=mode)

        return result
    except Exception as ex:
        return f"An error occurred: {str(ex)}"

