def analyse_ordering_patterns(product_details: List[Tuple[str, str]], chosen_product: Optional[str] = None) -> int:
    # Check if product_details is a list and chosen_product is a string if given

    if not isinstance(product_details, list) or (chosen_product is not None and not isinstance(chosen_product, str)):
        raise TypeError('Invalid input types.')

    # Check if product_details only contains tuples of strings

    for product_detail in product_details:
        if not isinstance(product_detail, tuple) or len(product_detail) != 2 or \
        not isinstance(product_detail[0], str) or not isinstance(product_detail[1], str):
            raise TypeError('In product details, each product detail should be a tuple containing two strings.')

    if chosen_product is None:
        # In this case, the number of ways to order all products with each specific discount code
        # is the product of the number of ways to order each product.
        # As each product has only one unique discount code available, the number of ways to order each 
        # product is 1. So, the total number of ways is 1**n = 1, where n is the number of products.
        return math.comb(len(product_details)) 

    else:
        # Only calculate combinations for the chosen_product
        for product, discount_code in product_details:
            if product == chosen_product:
                # If product is the chosen_product, return 1 since there's only one way of ordering 
                # a product with a specific discount code.
                return math.comb(1)

        # If the loop completes without returning, the chosen product was not found in products details.
        # In this case, return 0 since it's impossible to order the chosen product.
        return 0

